export function TickIcon({ id, size = 18, className, style }: TickIconProps & { id: keyof typeof GLYPHS | string }) {
  const glyph = GLYPHS[id];
  if (!glyph) return null;
  return (
    <svg width={size} height={size} viewBox={glyph.viewBox} className={className} style={style} fill="currentColor" aria-hidden>
      <g dangerouslySetInnerHTML={{ __html: glyph.body }} />
    </svg>
  );
}

