/** 今天 — the reference app's calendar icon with the live date digit. */
export function IconToday({ size = 18, className, style }: TickIconProps) {
  const day = new Date().getDate();
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" className={className} style={style} fill="currentColor" aria-hidden>
      <path fillRule="evenodd" d={TODAY_BASE + (TODAY_DIGITS[day] ?? '')} />
    </svg>
  );
}

