/** 最近7天 — the reference app's calendar icon with the live weekday code. */
export function IconNext7({ size = 18, className, style }: TickIconProps) {
  const letters = WEEKDAY_LETTERS[new Date().getDay()] ?? '';
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" className={className} style={style} fill="currentColor" aria-hidden>
      <path fillRule="evenodd" d={TODAY_BASE + letters} />
    </svg>
  );
}
